import{_ as s,l as o,o as e,c as n,v as t,p as l,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"关键路径","description":"","frontmatter":{"title":"关键路径","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/critical-path.md","filePath":"cs/critical-path.md","lastUpdated":1789023840000}'),h={name:"cs/critical-path.md"};function E(_,a,A,m,u,B){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="关键路径" tabindex="-1">关键路径 <a class="header-anchor" href="#关键路径" aria-label="Permalink to &quot;关键路径&quot;">​</a></h1><div class="epigraph"><p>电路的传播延迟不是「平均看起来多久」，而是输入到输出所有拓扑路径里最慢的那一条。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/gate-delay">组合逻辑时延</a>给每个门贴了 \\(t_{pd}\\) 与 \\(t_{cd}\\)。本课不重定义这两个量，也不从静态时序工具的 SDC 另起。缺口是：网表有许多输入-输出路径，后课周期、加法器选型、ALU 深度，要比的是<strong>那一条最坏和</strong>，不是某一条典型路径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单位延迟模型下，路径延迟是沿途门 \\(t_{pd}\\) 之和。电路 \\(t_{pd}\\) 取最大；那条路径叫关键路径。缺口因此不是新的门，而是：优化必须动这条路径——缩短非关键路径不提高时钟。假路径（功能上走不到的组合）可以标掉，本课承认存在，不把例外表写完。</p><p>后课<a href="/cs/mux-select">MUX</a>、CLA、单周期 <code>lw</code>，都先找出哪一段串联最长。</p><h3 id="关键路径不是「门最多的那条」" tabindex="-1">关键路径不是「门最多的那条」 <a class="header-anchor" href="#关键路径不是「门最多的那条」" aria-label="Permalink to &quot;关键路径不是「门最多的那条」&quot;">​</a></h3><p>扇入、扇出、线负载改写每级延迟。门数少但每级很重，可以比门数多的浅路径更慢。把「级数」与「延迟」当成同一数字，超前进位的分组理由会说不清。</p><p><span class="marginnote">Harris 用路径延迟比较实现。Patterson/Hennessy 把 CPU 周期钉在最长指令的组合路径上。本课仍无时钟：关键路径是组合云的直径。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从每个输入到每个输出做加权最长路（门延迟为边权）。输出再作为下一块输入时，把块当作超节点，块间再比。污染路径取最短，给后课保持时间用，不是本课的「关键」。</p>',11)),(e(),l(c,null,{default:r(()=>[p(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20GATES%5B%22%E5%B8%A6%20t_pd%20%E7%9A%84%E9%97%A8%E7%BD%91%22%5D%20--%3E%20PATHS%5B%22%E5%85%A8%E4%BD%93%E8%BE%93%E5%85%A5%E5%88%B0%E8%BE%93%E5%87%BA%E8%B7%AF%E5%BE%84%22%5D%0A%20%20PATHS%20--%3E%20CRIT%5B%22%E5%BB%B6%E8%BF%9F%E5%92%8C%E6%9C%80%E5%A4%A7%E8%80%85%22%5D%0A%20%20CRIT%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AMUX%20%E7%AD%89%E5%91%BD%E5%90%8D%E5%9D%97%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>行波加法的关键路径沿进位链，故 \\(t_{pd}=\\Theta(n)\\)。CLA 把这条链拆成 \\(g,p\\) 树，关键路径改走树高。后课单周期把「取指 + 译码 + ALU + 访存 + 写回 MUX」串成一条更长的关键路径；流水线再把它切开。本课只给「找最长」这一格。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不跑 STA 工具、不建 RC 抽取。不把异步环振的周期当关键路径——那不是同步约束。多周期路径（有意两拍才采样）后课才出现。</p><p>后课默认：比较两个组合实现，先比关键路径；后课数据通路的周期下界来自这条路径加建立时间。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>关键路径是最坏 \\(t_{pd}\\) 之和，决定组合块有多慢。</li><li>优化非关键路径不提高时钟。</li><li>门数与延迟不是同一尺子。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD (RISC-V)。</li></ul>',7))])}const C=s(h,[["render",E]]);export{f as __pageData,C as default};
